151	/** Re-load the active sheet so the screen shows what the store holds now. Loading the same id
152	 *  again is not observable (the current id already reads that), so the screen first loads a
153	 *  throwaway id, which has no one on it, and waits for the person rows to go; then it loads the
154	 *  sheet again and waits for rows to show. Rows that were on screen before may rightly not come
155	 *  back (someone retired since, say), so the wait is for any row, and for every row that is back
156	 *  to carry at least the claims it had; if none shows within the wait the screen is taken as it
157	 *  is and the test's own checks decide. The show-retired box and the as-of date, which belong to
158	 *  the screen, are put back if the loads reset them. */
159	export async function refresh(page: Page): Promise<void> {
160	  const sheet = (await page.getByTestId('sheet-current-id').textContent() ?? '').trim();
161	  const before = new Map<string, number>();
162	  for (const id of await ids(rows(page), 'person-row-')) before.set(id, await claimRows(row(page, id)).count());
163	  const retired = page.getByTestId('show-retired');
164	  const showRetiredWas = (await retired.count()) > 0 ? await retired.isChecked() : null;
165	  const asofWas = await shown(page.getByTestId('sheet-asof'));
166	  await loadSheet(page, sheet + '-reload');
167	  await expect.poll(() => rows(page).count(), { message: 'the throwaway sheet, which has no one on it, is on screen', timeout: LOAD_WAIT }).toBe(0);
168	  await loadSheet(page, sheet);
169	  if (showRetiredWas !== null && (await retired.isChecked()) !== showRetiredWas) await retired.setChecked(showRetiredWas);
170	  if (asofWas !== '' && (await shown(page.getByTestId('sheet-asof'))) !== asofWas) await setAsOf(page, asofWas);
171	  if (before.size === 0) return;
172	  const back = async () => {
173	    if ((await rows(page).count()) === 0) return false;
174	    for (const [id, n] of before) {
175	      const r = row(page, id);
176	      if ((await r.count()) > 0 && (await claimRows(r).count()) < n) return false;
177	    }
178	    return true;
179	  };
180	  const deadline = Date.now() + LOAD_WAIT;
181	  while (Date.now() < deadline && !(await back())) await page.waitForTimeout(50);
182	}
