648	/** close | soft-close | reopen: true when the period's closed flag changed. */
649	export async function periodAction(page: Page, name: string, action: string): Promise<boolean> {
650	  const r = page.getByTestId(`period-row-${name}`);
651	  const was = await shown(r.getByTestId('period-closed'));
