678	    && !(await page.getByTestId('settings-error').isVisible().catch(() => false)),
679	    page.getByTestId('settings-error'), 'save dated setting');
680	  if (ok) await page.waitForTimeout(300);     // the value may already have shown; let the save land
681	  return ok;
