694	export async function delegate(page: Page, f: { user: string; from: string; to: string }): Promise<boolean> {
695	  const lines = page.getByTestId('delegate-line');
696	  const was = await lines.count();
697	  await page.getByTestId('delegate-user').fill(f.user);
698	  await page.getByTestId('delegate-from').fill(f.from);
699	  await page.getByTestId('delegate-to').fill(f.to);
