711	// ---- audit -----------------------------------------------------------------------------------
712	
713	/** The audit lines written for this sheet, in file order. */
714	export function auditFor(sheet: string): string[] {
715	  if (!existsSync(AUDIT_FILE)) return [];
716	  return readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.includes(` sheet=${sheet} `));
717	}
718	
719	/** The sheet's audit lines are exactly these, in order; a line may carry further fields after
720	 *  the expected ones (a later feature may extend a line, never change or reorder its fields).
721	 *  A line may land a moment after the screen shows its result, so the file is re-read until
722	 *  it has as many lines as expected (lines are only ever appended), for AUDIT_WAIT at most. */
723	export async function expectAudit(sheet: string, expected: string[]): Promise<void> {
724	  let lines = auditFor(sheet);
725	  const deadline = Date.now() + AUDIT_WAIT;
726	  while (lines.length < expected.length && Date.now() < deadline) {
