729	  }
730	  expect(lines.length, `audit lines for ${sheet}:\n${lines.join('\n')}`).toBe(expected.length);
731	  lines.forEach((line, i) => {
732	    const e = expected[i];
733	    const ok = line === e || line.startsWith(e + ' ');
734	    expect(ok, `audit line ${i + 1}\n  expected: ${e}\n  actual:   ${line}`).toBe(true);
