746	    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
747	    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
748	    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
749	    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
750	    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
751	    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
752	    expect(await ui.archive(pg_uma)).toBe(false);
753	    await ui.refresh(pg_uma);
754	    await expect(pg_uma.getByTestId("sheet-archived")).toHaveText("no");
755	    const pg_vic = await ui.userPage(browser, "vic", sheet);
756	    expect(await ui.archive(pg_vic)).toBe(true);
757	    expect(await ui.archive(pg_vic)).toBe(false);
758	    expect(await ui.addClaim(pg_vic, p_ada, {"amount": "30.00"})).toBeNull();
759	    expect(await ui.claimAction(pg_vic, c_ada_1, "open")).toBe(false);

